import {securityActions,securityRequestAllowed} from './security-policy.mjs';
import {SessionError,policy} from './store.mjs';
export function createSecurityHandler({core,path,sessionCookie,loginCookie,cookies}){
 const html=(res,status,title,body)=>{res.writeHead(status,{'content-type':'text/html; charset=utf-8','cache-control':'no-store'});res.end(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Account security</title><body><main><h1>${title}</h1>${body}</main></body></html>`);};
 return async(req,res)=>{try{
  if(new URL(req.url,core.profile.origin).search)throw new SessionError('unexpected_parameters',400);
  const cs=cookies(req);let s;try{s=await core.authenticate(cs[sessionCookie]);}catch(error){if(req.method==='GET'&&error.code==='session_renewal_required'){const t=await core.start(cs[sessionCookie],cs[loginCookie],{returnTo:path});res.writeHead(303,{location:t.url,'cache-control':'no-store','set-cookie':`${loginCookie}=${t.login}; Secure; HttpOnly; SameSite=Lax; Path=/; Max-Age=${policy.transaction}`});res.end();return;}throw error;}
  if(req.method==='GET')return html(res,200,'Account security','<p>Passkeys and authenticators are available for your account. Privileged accounts require a second factor and recovery codes. Once enrolled, use a verified passkey, your authenticator, or a saved recovery code when signing in.</p><p>Each change requires you to sign in again. Credential changes sign out existing sessions in both apps. Save recovery codes in your password manager; each code works once.</p>'+Object.entries(securityActions).map(([action,label])=>`<form method="post" action="${path}"><input type="hidden" name="csrf" value="${s.csrf}"><input type="hidden" name="action" value="${action}"><button>${label}</button></form>`).join('')+'<p><a href="'+core.profile.issuer+'/account/account-security/signing-in">Manage saved authenticators and remove a lost device</a></p><p>Lost your authenticator? Use “Try another way” on the sign-in screen and enter a saved recovery code, then set up a replacement here. Forgot your password? Use the password-reset link on the sign-in screen.</p><p><a href="/">Return to app</a></p>');
  if(req.method!=='POST')throw new SessionError('method_not_allowed',405);
  if(!req.headers['content-type']?.startsWith('application/x-www-form-urlencoded'))throw new SessionError('content_type',415);
  let body='';for await(const chunk of req){body+=chunk;if(body.length>1024)throw new SessionError('body_limit',413);}const form=new URLSearchParams(body);
  if(form.size!==2||form.getAll('csrf').length!==1||form.getAll('action').length!==1||!securityRequestAllowed({origin:req.headers.origin,expectedOrigin:core.profile.origin,csrf:form.get('csrf'),expectedCsrf:s.csrf,action:form.get('action')}))throw new SessionError('security_request_rejected',403);
  const t=await core.start(cs[sessionCookie],cs[loginCookie],{action:form.get('action')});res.writeHead(303,{location:t.url,'cache-control':'no-store','set-cookie':`${loginCookie}=${t.login}; Secure; HttpOnly; SameSite=Lax; Path=/; Max-Age=${policy.transaction}`});res.end();
 }catch(error){const status=error instanceof SessionError?error.status:503;html(res,status,'Security settings unavailable','<p>Your session could not be verified. Return to the app and sign in before making a change.</p><a href="/">Return to app</a>');}};
}
